			'publishedAt' { conds << load.eq('published_at', gql_time(v)!) }
			'publishedAtNEQ' { conds << load.ne('published_at', gql_time(v)!) }
			'publishedAtIn' { conds << load.or(...gql_times(v)!.map(load.eq('published_at', it))) }
			'publishedAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('published_at', it)))
			}
			'publishedAtGT' { conds << load.gt('published_at', gql_time(v)!) }
			'publishedAtGTE' { conds << load.ge('published_at', gql_time(v)!) }
			'publishedAtLT' { conds << load.lt('published_at', gql_time(v)!) }
			'publishedAtLTE' { conds << load.le('published_at', gql_time(v)!) }
			'publishedAtIsNil' {
				conds << if v.as_bool() {
					load.is_null('published_at')
				} else {
					load.is_not_null('published_at')
