			}
			'body' {
				input.body = v.as_string()
			}
			'publishedAt' {
				input.published_at = gql_time(v)!
			}
			'clearPublishedAt' {
				input.clear_published_at = v.as_bool()
			}
			else {}
		}
	}
	return input
}

// resolve_comment_field resolves the columns of `Comment`.
fn resolve_comment_field(_ context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(comment_value((it as CommentNode).comment, info.field_name)))
}

fn comment_value(row models.Comment, field string) graphql.Value {
	return match field {
		'createdAt' { graphql.Value(row.created_at.format_rfc3339()) }
		'updatedAt' { graphql.Value(row.updated_at.format_rfc3339()) }
		'id' { graphql.Value(row.id.str()) }
		'userID' { graphql.Value(row.user_id.str()) }
		'ownerType' { graphql.Value(string(row.owner_type)) }
		'ownerID' { graphql.Value(row.owner_id.str()) }
		'parentID' {
			if v := row.parent_id { graphql.Value(v.str()) } else { graphql.null }
		}
		'body' { graphql.Value(string(row.body)) }
		'deletedAt' {
			if v := row.deleted_at { graphql.Value(v.format_rfc3339()) } else { graphql.null }
		}
		else { graphql.null }
	}
}

// graphql_where applies the `where` argument of a `Comment` list.
fn (q CommentQuery) graphql_where(args map[string]graphql.Value) !CommentQuery {
	if w := args['where'] {
		if w is map[string]graphql.Value {
			return q.where(...comment_where(w)!)
		}
	}
	return q
}

// graphql_args applies the arguments of a `Comment` list: `where`, `orderBy`,
// and `limit` and `offset`, bounded by `size`.
fn (q CommentQuery) graphql_args(args map[string]graphql.Value, size graphql.PageSize) !CommentQuery {
	page := graphql.list_args(args, size)!
	mut next := q.graphql_where(args)!
	if o := args['orderBy'] {
		orders := comment_order(o, false)!
		if orders.len > 0 {
			next = next.order_by(...orders)
		}
	}
	if limit := page.limit {
		next = next.limit(limit)
	}
	if offset := page.offset {
		next = next.offset(offset)
	}
	return next
}

// comment_order returns the orders of an `orderBy` of `Comment`, and with `with_key`,
// the key last, unless it orders by it already.
fn comment_order(v graphql.Value, with_key bool) ![]load.Order {
	mut items := v.as_list()
	if items.len == 0 && v.as_map().len > 0 {
		items = [v]
	}
	mut orders := []load.Order{}
	mut keyed := false
	for item in items {
		o := item.as_map()
		desc := (o['direction'] or { graphql.null }).as_string() == 'DESC'
		field := (o['field'] or { graphql.null }).as_string()
		match field {
			'CREATED_AT' {
				orders << load.Order{ column: 'Stamps.created_at', desc: desc, typ: 'time.Time' }
			}
			'UPDATED_AT' {
				orders << load.Order{ column: 'Stamps.updated_at', desc: desc, typ: 'time.Time' }
			}
			'ID' {
				orders << load.Order{ column: 'id', desc: desc, typ: 'i64' }
				keyed = true
			}
			'USER_ID' {
				orders << load.Order{ column: 'user_id', desc: desc, typ: 'i64' }
			}
			'OWNER_TYPE' {
				orders << load.Order{ column: 'owner_type', desc: desc, typ: 'string' }
			}
			'OWNER_ID' {
				orders << load.Order{ column: 'owner_id', desc: desc, typ: 'i64' }
			}
			'PARENT_ID' {
				orders << load.Order{ column: 'parent_id', desc: desc, typ: '?i64' }
			}
			'BODY' {
				orders << load.Order{ column: 'body', desc: desc, typ: 'string' }
			}
			'DELETED_AT' {
				orders << load.Order{ column: 'deleted_at', desc: desc, typ: '?time.Time' }
			}
			'REPLIES_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "comments" AS "t1" WHERE "t1"."parent_id" = "t0"."id" AND "t1"."deleted_at" IS NULL)', desc: desc, typ: 'int' }
			}
			else { return error('`${field}` is not a CommentOrderField') }
		}
	}
	if with_key && !keyed {
		// the key breaks ties, in the direction of the last order, as entgql's
		orders << load.Order{
			column: 'id'
			desc:   orders.len > 0 && orders.last().desc
			typ:    'i64'
		}
	}
	return orders
}

// comment_where returns the conditions of a `CommentWhereInput`.
fn comment_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
		if v is graphql.Null {
			continue
		}
		match key {
			'not' {
				conds << load.not(load.and(...comment_where(v.as_map())!))
			}
			'and' {
				for item in v.as_list() {
					conds << comment_where(item.as_map())!
				}
			}
			'or' {
				mut any := []load.Cond{}
				for item in v.as_list() {
					any << load.and(...comment_where(item.as_map())!)
				}
				conds << load.or(...any)
			}
			'createdAt' { conds << load.eq('Stamps.created_at', gql_time(v)!) }
			'createdAtNEQ' { conds << load.ne('Stamps.created_at', gql_time(v)!) }
			'createdAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.created_at', it)))
			}
			'createdAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.created_at', it)))
