		'Stamps.updated_at' { orm.Primitive(row.updated_at) }
		'id' { orm.Primitive(row.id) }
		'user_id' { orm.Primitive(row.user_id) }
		'body' { orm.Primitive(row.body) }
		'deleted_at' {
